@Timeout(90)
class LmdbBackupPublicationHintTest {

	private static final int HINT_BUDGET_BYTES = 1024 * 1024;
	private static final int BACKLOG_STAGES = 64;

	@Test
	void committedBytesSurviveBufferReuseAndAbortWithoutSourceReads(@TempDir Path directory) throws Exception {
		ObservedStore store = new ObservedStore(directory.resolve("live"));
		Path backups = directory.resolve("backups");
		PublicationGate gate = new PublicationGate();
		store.init();
		try {
			long baseline = fullBackup(store, backups);
			TripleStore triples = store.getBackingStore().getTripleStore();
			PostCommitBackupPublisher publisher = store.getBackingStore().backupPublisher();
			publisher.setBeforePublication(gate::pause);
			Statement kept = statement("kept", "original committed bytes ".repeat(128));
			add(store, kept);
			gate.awaitSelectedBatch();
			assertEquals(1, store.preparations.size());
			Stage committed = store.preparations.getFirst();
			assertEquals(baseline + 1, committed.transaction);
			byte[] expectedStage = stageBytes(committed, kept);
			assertTrue(expectedStage.length < LmdbBackupChunkCodec.MAX_DECODED_BYTES);
			assertArrayEquals(expectedStage, triples.readBackupStageHeader(committed.transaction));

			AtomicInteger physicalAborts = new AtomicInteger();
			triples.beforePhysicalCommitForTest = () -> {
				physicalAborts.incrementAndGet();
				throw new SailException("Abort after the source stage and its reused buffers have been written");
			};
			try {
				assertThrows(SailException.class,
						() -> add(store, statement("discarded", "overwritten aborted bytes ".repeat(512))));
			} finally {
				triples.beforePhysicalCommitForTest = null;
			}
			assertEquals(1, physicalAborts.get(), "The aborted commit must reach actual native staging");
			assertEquals(2, store.preparations.size());
			Stage aborted = store.preparations.getLast();
			assertEquals(committed.transaction + 1, aborted.transaction);
			assertNotEquals(committed.id, aborted.id);
			assertEquals(committed.id, triples.getBackupOutboxHead());
			assertEquals(committed.transaction, triples.getRequiredBackupTxnId());
			assertEquals(List.of(committed.transaction),
					triples.listBackupStageTransactions(baseline, Long.MAX_VALUE));
			assertArrayEquals(expectedStage, triples.readBackupStageHeader(committed.transaction),
					"The aborted native transaction must leave the committed source payload intact");

			gate.release();
			publisher.close();
			assertPublished(store, backups, baseline, List.of(kept), directory.resolve("exported"));
			assertEquals(committed.id, publisher.acknowledgement().identity());
			assertEquals(committed.transaction, publisher.acknowledgedTransactionId());
			try (var connection = store.getConnection()) {
				assertEquals(1L, connection.size());
			}
			assertEquals(0, store.sourceOpens.size(),
					"An eligible committed stage must publish its owned bytes after later buffer reuse and abort");
		} finally {
			gate.release();
			store.getBackingStore().getTripleStore().beforePhysicalCommitForTest = null;
			store.shutDown();
		}
	}

	@Test
	void boundedHintsIncludeTheSelectedBatchAndFallBackToNativeStages(@TempDir Path directory) throws Exception {
		ObservedStore store = new ObservedStore(directory.resolve("live"));
		Path backups = directory.resolve("backups");
		PublicationGate gate = new PublicationGate();
		store.init();
		try {
			long baseline = fullBackup(store, backups);
			TripleStore triples = store.getBackingStore().getTripleStore();
			PostCommitBackupPublisher publisher = store.getBackingStore().backupPublisher();
			publisher.setBeforePublication(gate::pause);
			store.notifyAcknowledgementAt.set(baseline + BACKLOG_STAGES);
			List<Statement> statements = new ArrayList<>();
			Map<Long, Integer> rawStageLengths = new LinkedHashMap<>();
			for (int index = 0; index < BACKLOG_STAGES; index++) {
				Statement next = statement("backlog-" + index, "stage-" + index + ':' + "q".repeat(24 * 1024));
				statements.add(next);
				add(store, next);
				if (index == 0) {
					// The first stage already belongs to a selected batch, but its input is not consumed yet.
					gate.awaitSelectedBatch();
				}
				Stage stage = store.preparations.getLast();
				assertEquals(baseline + index + 1, stage.transaction);
				byte[] expectedStage = stageBytes(stage, next);
				assertTrue(expectedStage.length < LmdbBackupChunkCodec.MAX_DECODED_BYTES,
						"Each backlog entry must be individually eligible as one complete raw chunk");
				assertArrayEquals(expectedStage, triples.readBackupStageHeader(stage.transaction));
				rawStageLengths.put(stage.transaction, expectedStage.length);
			}
			assertEquals(BACKLOG_STAGES, store.preparations.size());
			assertEquals(new ArrayList<>(rawStageLengths.keySet()),
					triples.listBackupStageTransactions(baseline, Long.MAX_VALUE));
			long allBytes = rawStageLengths.values().stream().mapToLong(Integer::longValue).sum();
			assertTrue(allBytes > HINT_BUDGET_BYTES, "The stopped publisher must exhaust the global hint budget");
			assertTrue(store.sourceOpens.isEmpty(), "The selected batch must remain stopped before input is opened");
			assertEquals(baseline, publisher.acknowledgedTransactionId());

			gate.release();
			assertTrue(store.acknowledgementReached.await(20, TimeUnit.SECONDS),
					"The first cohort must finish durable acknowledgement before the budget is reused");
			assertPublished(store, backups, baseline, statements, directory.resolve("exported"));
			Stage last = store.preparations.getLast();
			assertEquals(last.id, triples.getBackupOutboxHead());
			assertEquals(last.id, publisher.acknowledgement().identity());
			assertEquals(last.transaction, publisher.acknowledgedTransactionId());

			long cachedBytes = rawStageLengths.entrySet()
					.stream()
					.filter(entry -> !store.sourceOpens.contains(entry.getKey()))
					.mapToLong(Map.Entry::getValue)
					.sum();
			long fallbackStages = rawStageLengths.keySet().stream().filter(store.sourceOpens::contains).count();
			System.out.printf("Publication hints: stages=%d rawBytes=%d cachedBytes=%d fallbackStages=%d%n",
					BACKLOG_STAGES, allBytes, cachedBytes, fallbackStages);
			assertTrue(fallbackStages > 0, "Stages beyond the hint budget must still publish from durable native data");
			assertTrue(cachedBytes <= HINT_BUDGET_BYTES,
					"Selected but unconsumed stages must count against the same 1 MiB budget as pending stages");
			Statement afterDrain = statement("after-drain", "released budget is available again");
			add(store, afterDrain);
			publisher.close();
			assertPublished(store, backups, last.transaction, List.of(afterDrain), directory.resolve("after-drain"));
			assertEquals(last.transaction + 1, publisher.acknowledgedTransactionId());
			assertEquals(store.preparations.getLast().id, publisher.acknowledgement().identity());
			assertTrue(cachedBytes > 0,
					"An eligible prefix must use owned hints while the remaining backlog falls back to native data");
			assertTrue(!store.sourceOpens.contains(last.transaction + 1),
					"Durable acknowledgement must release hint capacity for the next committed stage");
		} finally {
			gate.release();
			store.shutDown();
		}
	}

	private static long fullBackup(LmdbStore store, Path backups) {
		return store.getBackupService()
				.createBackup(BackupRequest.builder(backups, BackupType.FULL).build())
				.getEndTransactionId();
	}

	private static void assertPublished(LmdbStore store, Path backups, long baseline, List<Statement> statements,
			Path destination) throws IOException {
		LmdbBackupServiceImpl service = (LmdbBackupServiceImpl) store.getBackupService();
		long end = baseline + statements.size();
		assertEquals(end, service.createBackup(BackupRequest.builder(backups, BackupType.INCREMENTAL)
				.sinceTransactionId(baseline)
				.build()).getEndTransactionId());
		List<Path> logs = service.exportTransactionLogs(backups, baseline, end, destination);
		assertEquals(statements.size(), logs.size());
		for (int index = 0; index < statements.size(); index++) {
			ByteArrayOutputStream expected = new ByteArrayOutputStream();
			LmdbBackupDeltaCodec.write(expected, List.of(new Record(true, true, statements.get(index))),
					baseline + index, store.getBackingStore().backupJournalState().generation());
			try (var input = new GZIPInputStream(Files.newInputStream(logs.get(index)))) {
				assertArrayEquals(expected.toByteArray(), input.readAllBytes(),
						"Every archived journal must preserve the exact committed record bytes and predecessor");
			}
		}
	}

	private static byte[] stageBytes(Stage stage, Statement statement) throws IOException {
		ByteArrayOutputStream expected = new ByteArrayOutputStream();
		try (DataOutputStream output = new DataOutputStream(expected)) {
			PostCommitBackupPublisher.writeStageHeader(output, stage);
			LmdbBackupDeltaCodec.writeRecords(output, List.of(new Record(true, true, statement)));
		}
		return expected.toByteArray();
	}

	private static Statement statement(String name, String label) {
		var values = SimpleValueFactory.getInstance();
		return values.createStatement(values.createIRI("urn:backup-hint:" + name),
				values.createIRI("urn:backup-hint:p"), values.createLiteral(label));
	}

	private static void add(LmdbStore store, Statement statement) {
		try (var connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(statement.getSubject(), statement.getPredicate(), statement.getObject());
			connection.commit();
		}
	}

	private static final class ObservedStore extends LmdbStore {
		private final List<Stage> preparations = new CopyOnWriteArrayList<>();
		private final List<Long> sourceOpens = new CopyOnWriteArrayList<>();
		private final AtomicLong notifyAcknowledgementAt = new AtomicLong(Long.MAX_VALUE);
		private final CountDownLatch acknowledgementReached = new CountDownLatch(1);

		private ObservedStore(Path directory) {
			super(directory.toFile(), new LmdbStoreConfig().setBackupJournalEnabled(true));
		}

		@Override
		LmdbSailStore createBackingStore(File data, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			return new LmdbSailStore(data, properties, config, sketches, ValueStore::new,
					(triples, props, configuration, values) -> new TripleStore(triples, props, configuration, values) {
						@Override
						void setPendingBackupStage(Stage stage, List<Record> records) {
							preparations.add(stage);
							super.setPendingBackupStage(stage, records);
						}

						@Override
						void acknowledgeBackupStages(long transaction) {
							super.acknowledgeBackupStages(transaction);
							if (transaction >= notifyAcknowledgementAt.get()) {
								acknowledgementReached.countDown();
							}
						}

						@Override
						InputStream openBackupStage(long transaction) {
							sourceOpens.add(transaction);
							return super.openBackupStage(transaction);
						}
					});
		}
	}

	private static final class PublicationGate {
		private final CountDownLatch selected = new CountDownLatch(1);
		private final CountDownLatch released = new CountDownLatch(1);

		private void pause() {
			selected.countDown();
			try {
				assertTrue(released.await(60, TimeUnit.SECONDS),
						"The test must release the selected publication batch");
			} catch (InterruptedException interrupted) {
				Thread.currentThread().interrupt();
				throw new AssertionError(interrupted);
			}
		}

		private void awaitSelectedBatch() throws InterruptedException {
			assertTrue(selected.await(20, TimeUnit.SECONDS),
					"The committed stage must reach a selected publisher batch");
		}

		private void release() {
			released.countDown();
		}
	}
}
